import fs from 'node:fs';import path from 'node:path';import {createHash} from 'node:crypto';
export const hash=b=>createHash('sha256').update(b).digest('hex');
const checkedRead=f=>{const s=fs.lstatSync(f);if(!s.isFile()||s.isSymbolicLink())throw Error('PERSISTENT_FILE_TYPE');return fs.readFileSync(f);};
const writeSynced=(f,b,flag='wx')=>{const fd=fs.openSync(f,flag,0o600);try{fs.writeSync(fd,b);fs.fsyncSync(fd);}finally{fs.closeSync(fd);}};
export function provisionGuard(dir,approvalHash){if(!path.isAbsolute(dir)||fs.existsSync(dir))throw Error('NEW_PERSISTENT_DIRECTORY_REQUIRED');fs.mkdirSync(dir,{recursive:true});writeSynced(path.join(dir,'requests.ndjson'),'');writeSynced(path.join(dir,'activation.json'),JSON.stringify({project:'vulture-judge-003',approvalSha256:approvalHash,createdAt:new Date().toISOString(),providerCalls:0}));writeSynced(path.join(dir,'integrity.json'),JSON.stringify({schema:1,approvalHash,bytes:0,sha256:hash('')}));}
export function verifyPersistent(dir,approvalHash){try{if(!path.isAbsolute(dir)||fs.lstatSync(dir).isSymbolicLink())throw Error('PATH');const activation=JSON.parse(checkedRead(path.join(dir,'activation.json'))),seal=JSON.parse(checkedRead(path.join(dir,'integrity.json'))),log=checkedRead(path.join(dir,'requests.ndjson'));if(activation.project!=='vulture-judge-003'||activation.approvalSha256!==approvalHash||seal.schema!==1||seal.approvalHash!==approvalHash||seal.bytes!==log.length||seal.sha256!==hash(log)||fs.existsSync(path.join(dir,'pending.json')))throw Error('INTEGRITY');return {bytes:log.length,sha256:hash(log)};}catch{throw Error('PERSISTENT_STATE_INVALID_FAIL_CLOSED');}}
export function attachPersistentGuard(journal,dir,approvalHash){verifyPersistent(dir,approvalHash);const append=journal.append.bind(journal);journal.append=event=>{verifyPersistent(dir,approvalHash);const pending=path.join(dir,'pending.json'),temp=path.join(dir,'integrity.next');writeSynced(pending,JSON.stringify({schema:1,approvalHash,eventSha256:hash(JSON.stringify(event))}));try{append(event);const b=checkedRead(path.join(dir,'requests.ndjson'));writeSynced(temp,JSON.stringify({schema:1,approvalHash,bytes:b.length,sha256:hash(b)}));fs.renameSync(temp,path.join(dir,'integrity.json'));fs.unlinkSync(pending);}catch{throw Error('PERSISTENT_WRITE_INCOMPLETE_FAIL_CLOSED');}};return journal;}
